mapper.select:
SELECT SEC_INFO.SEC_ID SECID, SEC_INFO.BOND_NAME SECFULLNAME, SEC_INFO.BOND_ABBREVIATION SECNAME, SEC_INFO.TRADING_PLACES, SEC_INFO.REGISTERED_CUSTODIAN, SEC_INFO.RAISE_MODE, CASE WHEN SEC_INFO.SECONDARY_CLASSIFICATION in ('同业存单', '证券公司短期融资券') THEN RDI_RELEASE_INFO.ISSUE_METHOD ELSE RELEASE_INFO.ISSUING_METHOD END as ISSUING_METHOD,
CASE WHEN SEC_INFO.SECONDARY_CLASSIFICATION in ('同业存单', '证券公司短期融资券') THEN null ELSE RELEASE_INFO.BIDDING_METHOD END as BIDDING_METHOD,
CASE WHEN SEC_INFO.SECONDARY_CLASSIFICATION in ('同业存单', '证券公司短期融资券') THEN null ELSE RELEASE_INFO.TENDER_TARGET END as TENDER_TARGET,
CASE WHEN SEC_INFO.SECONDARY_CLASSIFICATION in ('同业存单', '证券公司短期融资券') THEN null ELSE RELEASE_INFO.ADDITIONAL_BATCHES END as ADDITIONAL_BATCHES,
CASE WHEN SEC_INFO.SECONDARY_CLASSIFICATION in ('同业存单', '证券公司短期融资券') THEN ROUND(RDI_RELEASE_INFO.ISSUE_SIZE * 10000, 2) ELSE ROUND(RELEASE_INFO.ISSUE_SIZE / 10000, 2) END as ISSUE_SIZE,
CASE WHEN SEC_INFO.SECONDARY_CLASSIFICATION in ('同业存单', '证券公司短期融资券') THEN TO_DATE(RDI_RELEASE_INFO.ISSUE_DATE, 'yyyy-MM-dd') ELSE TO_DATE(RELEASE_INFO.ISSUE_DATE, 'yyyy-MM-dd') END as ISSUE_DATE,
CASE WHEN SEC_INFO.SECONDARY_CLASSIFICATION in ('同业存单', '证券公司短期融资券') THEN TO_DATE(RDI_RELEASE_INFO.EVENT_DATE, 'yyyy-MM-dd') ELSE TO_DATE(RELEASE_INFO.PAYMENT_DEADLINE, 'yyyy-MM-dd') END as EVENT_DATE,
CASE WHEN SEC_INFO.SECONDARY_CLASSIFICATION in ('同业存单', '证券公司短期融资券') THEN null ELSE TO_DATE(RELEASE_INFO.DEBT_REGISTRATION_DATE, 'yyyy-MM-dd') END as DEBT_REGISTRATION_DATE,
CASE WHEN SEC_INFO.SECONDARY_CLASSIFICATION in ('同业存单', '证券公司短期融资券') THEN null ELSE TO_DATE(RELEASE_INFO.LISTING_DATE, 'yyyy-MM-dd') END as LISTING_DATE,
CASE WHEN SEC_INFO.SECONDARY_CLASSIFICATION in ('同业存单', '证券公司短期融资券') THEN null ELSE RELEASE_INFO.LISTING_CODE END as LISTING_CODE,
CASE WHEN SEC_INFO.SECONDARY_CLASSIFICATION in ('同业存单', '证券公司短期融资券') THEN null ELSE SEC_INFO.CROSS_MARKET_CODE END as CROSS_MARKET_CODE,
CASE WHEN SEC_INFO.SECONDARY_CLASSIFICATION in ('同业存单', '证券公司短期融资券') THEN TO_DATE(RDI_RELEASE_INFO.INTEREST_ACCRUAL_DATE, 'yyyy-MM-dd') ELSE TO_DATE(RELEASE_INFO.INTEREST_ACCRUAL_DATE, 'yyyy-MM-dd') END as INTEREST_ACCRUAL_DATE, SEC_INFO.VALUE_DATE, SEC_INFO.EXPIRY_DATE, SEC_INFO.PRIMARY_CLASSIFICATION, SEC_INFO.SECONDARY_CLASSIFICATION, SEC_INFO.VARIETY_OF_COUPONS, SEC_INFO.INTEREST_PAYMENT_FREQUENCY, SEC_INFO.RATE_TYPE, SEC_INFO.CURRENCY CCY, CASE WHEN SEC_INFO.SECONDARY_CLASSIFICATION in ('同业存单', '证券公司短期融资券') THEN RDI_RELEASE_INFO.ISSUE_PX ELSE RELEASE_INFO.ISSUE_PX END as ISSUE_PX,
CASE WHEN SEC_INFO.SECONDARY_CLASSIFICATION in ('同业存单', '证券公司短期融资券') THEN RDI_RELEASE_INFO.STIPULATION_VALUE ELSE RELEASE_INFO.STIPULATION_VALUE END as STIPULATION_VALUE,
CASE WHEN SEC_INFO.SECONDARY_CLASSIFICATION in ('同业存单', '证券公司短期融资券') THEN RDI_RELEASE_INFO.SINGLE_MIN_SUB_AMT * 10000 ELSE ROUND(RELEASE_INFO.SINGLE_MIN_SUB_AMT / 10000, 2) END as SINGLE_MIN_SUB_AMT,
CASE WHEN SEC_INFO.SECONDARY_CLASSIFICATION in ('同业存单', '证券公司短期融资券') THEN RDI_RELEASE_INFO.SINGLE_MAX_SUB_AMT * 10000 ELSE ROUND(RELEASE_INFO.SINGLE_MAX_SUB_AMT / 10000, 2) END as SINGLE_MAX_SUB_AMT,
CASE WHEN SEC_INFO.SECONDARY_CLASSIFICATION in ('同业存单', '证券公司短期融资券') THEN RDI_RELEASE_INFO.REMARK ELSE null END as REMARK FROM INTERF_WIND_UNRELEASE_SEC_INFO SEC_INFO LEFT JOIN INTERF_WIND_RELEASE_INFO RELEASE_INFO ON SEC_INFO.SEC_ID = RELEASE_INFO.SEC_ID LEFT JOIN INTERF_RDI_RELEASE_INFO RDI_RELEASE_INFO ON RDI_RELEASE_INFO.SECURITY_ID = SEC_INFO.SEC_ID
SEC_INFO.VALUE_DATE < to_date(#{platformDate}, '%Y-%m-%d')
AND PAYHSRCSECINFO.SECID = #{secId,jdbcType=VARCHAR}
AND PAYHSRCSECINFO.MARKET = #{market,jdbcType=VARCHAR}
AND PAYHSRCSECINFO.institution = #{institution,jdbcType=VARCHAR}
AND PAYHSRCSECINFO.ISSUERSHORT = #{issuer,jdbcType=VARCHAR}
AND PAYHSRCSECINFO.PUBENDDATE >= #{issueDateStart,jdbcType=DATE}
AND PAYHSRCSECINFO.PUBENDDATE <= #{issueDateEnd,jdbcType=DATE}
AND PAYHSRCSECINFO.VDATE >= #{vdateStart,jdbcType=DATE}
AND PAYHSRCSECINFO.VDATE <= #{vdateEnd,jdbcType=DATE}
AND PAYHSRCSECINFO.MDATE >= #{mdateStart,jdbcType=DATE}
AND PAYHSRCSECINFO.MDATE <= #{mdateEnd,jdbcType=DATE}
AND PAYHSRCSECOPTION.THEORYOPTIONPAYDAY >= #{theOryOptionPayDayStart,jdbcType=DATE}
AND PAYHSRCSECOPTION.THEORYOPTIONPAYDAY <= #{theOryOptionPayDayEnd,jdbcType=DATE}
AND PAYHSRCSECINFO.COUPONSPECIES = #{couponSpecies,jdbcType=VARCHAR}
AND PAYHSRCSECINFO.INTERESTRATE = #{interestRate,jdbcType=VARCHAR}
AND PAYHSRCSECINFO.PAYCYCLE = #{payCycle,jdbcType=VARCHAR}
AND PAYHSRCSECINFO.CCY = #{ccy,jdbcType=VARCHAR}
AND PAYHSRCSECINFO.ISSUS = #{isSus,jdbcType=VARCHAR}
AND PAYHSRCSECINFO.ISSUS = #{isSus,jdbcType=VARCHAR}
AND ( PAYHSRCSECINFO.CALLOPTION = 'Y' OR PAYHSRCSECINFO.PUTOPTION = 'Y')
AND ( PAYHSRCSECINFO.CALLOPTION = 'N' AND PAYHSRCSECINFO.PUTOPTION = 'N')
AND PAYHSRCSECOPTION.OPTIONTYPE = #{optionType,jdbcType=VARCHAR}
AND PAYHSRCSECRATING2.RATING in (#{zxGrade,jdbcType=VARCHAR})
AND PAYHSRCSECRATING.RATING in (#{ztGrade,jdbcType=VARCHAR})
AND ( PAYHSRCSECINFO.SECID like '%' || #{search} || '%' OR PAYHSRCSECINFO.MARKET like '%' || #{search} || '%' OR PAYHSRCSECINFO.institution like '%' || #{search} || '%' OR PAYHSRCSECINFO.ISSUERSHORT like '%' || #{search} || '%' OR to_char(PAYHSRCSECINFO.PUBENDDATE,'yyyy-MM-dd') = #{search} OR to_char(PAYHSRCSECINFO.VDATE,'yyyy-MM-dd') = #{search} OR to_char(PAYHSRCSECINFO.MDATE,'yyyy-MM-dd') = #{search} OR to_char(PAYHSRCSECOPTION.THEORYOPTIONPAYDAY,'yyyy-MM-dd') = #{search} OR PAYHSRCSECINFO.COUPONSPECIES like '%' || #{search} || '%' OR PAYHSRCSECINFO.INTERESTRATE like '%' || #{search} || '%' OR PAYHSRCSECINFO.PAYCYCLE like '%' || #{search} || '%' OR PAYHSRCSECINFO.CCY like '%' || #{search} || '%' OR PAYHSRCSECINFO.ISSUS like '%' || #{search} || '%' OR PAYHSRCSECOPTION.OPTIONTYPE like '%' || #{search} || '%' OR PAYHSRCSECRATING2.RATING like '%' || #{search} || '%' OR PAYHSRCSECRATING.RATING like '%' || #{search} || '%' )
ORDER BY PRIMARY_CLASSIFICATION, SECONDARY_CLASSIFICATION
